/* ===== IONICONS LOCAL & CDN FALLBACK DEFINITION ===== */
@font-face {
  font-family: 'Ionicons';
  font-style: normal;
  font-weight: normal;
  font-display: swap;
  src: url('./fonts/ionicons.woff2?v=4.5.10-1') format('woff2'),
    url('./fonts/ionicons.woff?v=4.5.10-1') format('woff'),
    url('./fonts/ionicons.ttf?v=4.5.10-1') format('truetype'),
    url('https://cdn.jsdelivr.net/npm/ionicons@4.5.10-1/dist/fonts/ionicons.woff2') format('woff2');
}

.ion-ios-chatboxes,
.ion-ios-close,
.qodef-icon-ionicons,
[class*="ion-"] {
  font-family: 'Ionicons' !important;
  speak: none;
  font-style: normal;
  font-weight: normal;
  font-variant: normal;
  text-transform: none;
  text-rendering: auto;
  line-height: 1;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.ion-ios-chatboxes:before {
  content: "\f3fa" !important;
  font-family: 'Ionicons' !important;
  display: inline-block;
}

.ion-ios-close:before {
  content: "\f2f8" !important;
  font-family: 'Ionicons' !important;
  display: inline-block;
}

/* ===== FONT AWESOME 5 LOCAL & CDN FALLBACK DEFINITION ===== */
@font-face {
  font-family: 'Font Awesome 5 Free';
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url('./webfonts/fa-regular-400.woff2') format('woff2'),
    url('https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.4/webfonts/fa-regular-400.woff2') format('woff2');
}

@font-face {
  font-family: 'Font Awesome 5 Free';
  font-style: normal;
  font-weight: 900;
  font-display: swap;
  src: url('./webfonts/fa-solid-900.woff2') format('woff2'),
    url('https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.4/webfonts/fa-solid-900.woff2') format('woff2');
}

@font-face {
  font-family: 'Font Awesome 5 Brands';
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url('./webfonts/fa-brands-400.woff2') format('woff2'),
    url('https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.4/webfonts/fa-brands-400.woff2') format('woff2');
}

.fa,
.fas {
  font-family: 'Font Awesome 5 Free' !important;
  font-weight: 900 !important;
}

.far {
  font-family: 'Font Awesome 5 Free' !important;
  font-weight: 400 !important;
}

.fab {
  font-family: 'Font Awesome 5 Brands' !important;
  font-weight: 400 !important;
}

/* ===== inline style ===== */
img:is([sizes=auto i], [sizes^="auto," i]) {
  contain-intrinsic-size: 3000px 1500px
}


